## ---- 11: Tidymodels Workflow  (qmd line 635) -----------------------------------------

library(tidymodels)
library(bonsai)      # provides the lightgbm engine for parsnip

md <- monthly_panel %>%
  mutate(month = as.Date(month),
         prepay_event = factor(prepay_event)) %>%
  arrange(month)

splits <- initial_time_split(md, prop = 0.8)
train  <- training(splits); test <- testing(splits)

rec <- recipe(prepay_event ~ ., data = train) %>%
  update_role(loan_id, month, month_id, new_role = "id") %>%
  step_rm(smm_event, event_type, smm, log_smm) %>%
  step_dummy(all_nominal_predictors()) %>%
  step_normalize(all_numeric_predictors())

spec <- boost_tree(trees = tune(), tree_depth = tune(),
                   learn_rate = tune()) %>%
  set_engine("lightgbm") %>% set_mode("classification")

wf <- workflow() %>% add_recipe(rec) %>% add_model(spec)

folds <- sliding_period(train, month, "month",
                        lookback = 36, assess_stop = 12, step = 12)

res <- tune_grid(wf, resamples = folds, grid = 20,
                 metrics = metric_set(roc_auc, brier_class))

best <- select_best(res, metric = "roc_auc")
final <- finalize_workflow(wf, best) %>% fit(train)


## ---- 12: Population Stability Index  (qmd line 671) ----------------------------------

psi <- function(actual, expected, n_bins = 10) {
  breaks <- quantile(expected, probs = seq(0, 1, length.out = n_bins + 1))
  e_bins <- table(cut(expected, breaks, include.lowest = TRUE)) / length(expected)
  a_bins <- table(cut(actual,   breaks, include.lowest = TRUE)) / length(actual)
  sum((a_bins - e_bins) * log(a_bins / e_bins), na.rm = TRUE)
}

psi(actual   = monthly_panel$refi_incentive[monthly_panel$year >= 2024],
    expected = monthly_panel$refi_incentive[monthly_panel$year <= 2022])


